import{_ as a,o,c as t,a5 as s}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"効果音と読み上げを設定する","description":"","frontmatter":{"title":"効果音と読み上げを設定する","docId":"user.plugins.audio","translationKey":"user.plugins.audio","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"b6be887705d13dfe120f3e07dc4006ec0efa1472b6dbe0ccfc1ebfc1e83f3672","translationRevision":"4e487531c65e1735032dad5eff7d67a5b867d13d86d29af6f4e49c5177e97d16","order":20},"headers":[],"relativePath":"ja/user/plugins/audio.md","filePath":"ja/user/plugins/audio.md","lastUpdated":1794611623000}'),r={name:"ja/user/plugins/audio.md"};function d(i,e,n,l,c,u){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="set-up-sounds-and-speech" tabindex="-1">効果音と読み上げを設定する <a class="header-anchor" href="#set-up-sounds-and-speech" aria-label="Permalink to &quot;効果音と読み上げを設定する {#set-up-sounds-and-speech}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>混雑した LIVE に音声を連動させる前に、予測できる音を再生します。正常な出力機器と対応する既存音声ファイルが必要です。ローカルの <strong>サウンドを再生</strong> (<code>audio.play</code>) は組み込みアクションです。SonicBoom などの読み上げ連携には専用プラグイン・サービスの設定が必要です。</p><h2 id="test-a-local-sound" tabindex="-1">ローカル音声を試す <a class="header-anchor" href="#test-a-local-sound" aria-label="Permalink to &quot;ローカル音声を試す {#test-a-local-sound}&quot;">​</a></h2><ol><li><strong>自動化 → アクション</strong> で <strong>サウンドを再生</strong> (<code>audio.play</code>) を作り、メディア選択で既存ファイルを指定します。</li><li>最初は音量 <code>0.2</code> にします。範囲は <code>0</code>～<code>1</code> で、ゼロは無音です。</li><li>重複時の方針を選びます。<code>allow</code> は同時再生、<code>restart</code> は最初から再生、<code>drop</code> は再生中の新しい要求を無視します。</li><li>保存して設定を読み、<strong>テストを実行</strong> を選びます。このテストでは実際に音が鳴ることがあります。</li><li>目的の機器で聞きます。ローカル再生が成功してから、控えめな<a href="./../automations/recipes.html">フィルターとクールダウン</a> を持つイベントに関連付けます。</li></ol><p>アクションはパスに基づくメディア参照を保持し、音声ファイルを DB にコピーしません。ファイルをそのパスに保ち、移行やバックアップでは別途含めてください。</p><h2 id="configure-optional-speech" tabindex="-1">任意の読み上げ機能を設定する <a class="header-anchor" href="#configure-optional-speech" aria-label="Permalink to &quot;任意の読み上げ機能を設定する {#configure-optional-speech}&quot;">​</a></h2><p>信頼できる読み上げプラグインを <a href="./">プラグイン</a> からインストールします。接続・設定でサービスアドレス、認証、プロバイダー、言語、音声・プロファイルを確認します。音声カタログを読み込んでから、機密性のない短文をテストします。音声がない場合は架空の ID で代用せず、カタログ、所有権、プロバイダーの不一致を調べます。</p><p>SonicBoom では合成、再生受付、聞こえるまでの完了は別の結果です。待機列への追加や開始応答だけでは、人が聞けたことは確認できません。クローン音声はチャットの到着より遅い場合があるため、待機列・飽和の診断を確認し、イベント受付数を制限します。</p><h2 id="expected-result-status-and-recovery" tabindex="-1">期待される結果・提供状況と対処 <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;期待される結果・提供状況と対処 {#expected-result-status-and-recovery}&quot;">​</a></h2><p>ホストが音声対応を通知していればローカル再生を利用できます。読み上げはインストール済みプラグインと接続可能なサービスに依存し、各プロバイダー・機器・プラットフォームでの動作は保証されません。無音ならファイル、音量、出力機器、一時停止、実行エラーを確認します。読み上げ失敗ではサービスと音声カタログを調べてから再試行します。配信中の繰り返しテストを避け、<a href="./../preferences/troubleshooting.html">診断</a> ではトークンや読み上げた非公開文を共有しないでください。</p>',11)])])}const f=a(r,[["render",d]]);export{h as __pageData,f as default};
